INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'disaster', 'n.', '/dɪˈzɑːstə/', '灾难;灾祸', 'An earthquake is one of the most frightening natural disasters.', '地震是最令人恐惧的自然灾难之一。', 'Disaster and Hope', 1, 0, 'senior', 'wordlist', 'required3', 'U6', 'a natural disaster', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'hope', 'n./v.', '/həʊp/', '希望;盼望', 'Even in the worst disaster, kind words can give people hope.', '即使在最严重的灾难中,善意的话也能给人希望。', 'Disaster and Hope', 2, 0, 'senior', 'wordlist', 'required3', 'U6', 'give people hope', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'hurricane', 'n.', '/ˈhʌrɪkən/', '飓风', 'The hurricane tore the roofs off many houses near the coast.', '飓风把海岸边许多房屋的屋顶都掀掉了。', 'Disaster and Hope', 3, 0, 'senior', 'wordlist', 'required3', 'U6', 'a powerful hurricane', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'typhoon', 'n.', '/ˌtaɪˈfuːn/', '台风', 'A strong typhoon brought heavy rain and huge waves to the city.', '一场强台风给这座城市带来了暴雨和巨浪。', 'Disaster and Hope', 4, 0, 'senior', 'wordlist', 'required3', 'U6', 'a strong typhoon', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tsunami', 'n.', '/tsʊˈnɑːmi/', '海啸', 'The earthquake under the sea caused a giant tsunami.', '海底地震引发了一场巨大的海啸。', 'Disaster and Hope', 5, 0, 'senior', 'wordlist', 'required3', 'U6', 'a giant tsunami', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'earthquake', 'n.', '/ˈɜːθkweɪk/', '地震', 'When the earthquake hit, the whole building began to shake.', '地震来袭时,整栋楼开始摇晃。', 'Disaster and Hope', 6, 0, 'senior', 'wordlist', 'required3', 'U6', 'a strong earthquake', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'flood', 'n./v.', '/flʌd/', '洪水;淹没', 'Heavy rain caused a terrible flood that turned the streets into rivers.', '暴雨引发了可怕的洪水,把街道变成了河流。', 'Disaster and Hope', 7, 0, 'senior', 'wordlist', 'required3', 'U6', 'a terrible flood', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'drought', 'n.', '/draʊt/', '干旱', 'After months of drought, not a single drop of rain had fallen.', '数月干旱过后,没有落下一滴雨。', 'Disaster and Hope', 8, 0, 'senior', 'wordlist', 'required3', 'U6', 'a long drought', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wildfire', 'n.', '/ˈwaɪldfaɪə/', '野火;山火', 'The wildfire spread across the dry hills within a few hours.', '山火在几个小时内就蔓延到了干燥的山丘上。', 'Disaster and Hope', 9, 0, 'senior', 'wordlist', 'required3', 'U6', 'spread like a wildfire', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'avalanche', 'n.', '/ˈævəlɑːntʃ/', '雪崩', 'Heavy snow led to an avalanche that buried a mountain road.', '大雪引发雪崩,埋住了一条山路。', 'Disaster and Hope', 10, 0, 'senior', 'wordlist', 'required3', 'U6', 'be buried by an avalanche', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'blizzard', 'n.', '/ˈblɪzəd/', '暴风雪', 'A blizzard brought metres of snow and trapped the villagers indoors.', '一场暴风雪带来数米厚的积雪,把村民困在了室内。', 'Disaster and Hope', 11, 0, 'senior', 'wordlist', 'required3', 'U6', 'a heavy blizzard', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'landslide', 'n.', '/ˈlændslaɪd/', '山崩;滑坡', 'Days of rain caused a landslide that blocked the only road out.', '连日降雨引发滑坡,堵住了唯一的出路。', 'Disaster and Hope', 12, 0, 'senior', 'wordlist', 'required3', 'U6', 'cause a landslide', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'erupt', 'v.', '/ɪˈrʌpt/', '(火山)爆发;喷发', 'When the volcano began to erupt, everyone ran for safety.', '火山开始喷发时,所有人都跑去避险。', 'Disaster and Hope', 13, 0, 'senior', 'wordlist', 'required3', 'U6', 'a volcano erupts', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'occur', 'v.', '/əˈkɜː/', '发生', 'Experts say such floods occur more often because of climate change.', '专家说,由于气候变化,这样的洪水发生得更频繁了。', 'Disaster and Hope', 14, 0, 'senior', 'wordlist', 'required3', 'U6', 'disasters occur', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'claim', 'v.', '/kleɪm/', '(灾难等)夺去(生命);声称', 'The avalanche claimed the lives of more than two hundred people.', '这场雪崩夺去了两百多人的生命。', 'Disaster and Hope', 15, 0, 'senior', 'wordlist', 'required3', 'U6', 'claim many lives', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'threaten', 'v.', '/ˈθretn/', '威胁;危及', 'The rising water began to threaten the homes along the river.', '上涨的河水开始威胁到河边的房屋。', 'Disaster and Hope', 16, 0, 'senior', 'wordlist', 'required3', 'U6', 'threaten people''s lives', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'threat', 'n.', '/θret/', '威胁;可能带来危险的事物', 'Floods are a common threat to towns built near the coast.', '洪水是对建在海岸边的城镇的常见威胁。', 'Disaster and Hope', 17, 0, 'senior', 'wordlist', 'required3', 'U6', 'a common threat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'crisis', 'n.', '/ˈkraɪsɪs/', '危机', 'The long drought led to a serious food crisis in the region.', '长期干旱导致该地区出现严重的粮食危机。', 'Disaster and Hope', 18, 0, 'senior', 'wordlist', 'required3', 'U6', 'a food crisis', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'emergency', 'n.', '/ɪˈmɜːdʒənsi/', '紧急情况;突发事件', 'China quickly sent emergency aid to the area hit by the earthquake.', '中国迅速向受地震影响的地区送去紧急援助。', 'Disaster and Hope', 19, 0, 'senior', 'wordlist', 'required3', 'U6', 'emergency aid', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rescue', 'n./v.', '/ˈreskjuː/', '营救;解救', 'An international rescue team searched the ruins for survivors.', '一支国际救援队在废墟中搜寻幸存者。', 'Disaster and Hope', 20, 0, 'senior', 'wordlist', 'required3', 'U6', 'a rescue team', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shelter', 'n.', '/ˈʃeltə/', '庇护;掩蔽处;避难所', 'When the storm hit, the family found shelter in the school hall.', '暴风雨来袭时,这家人在学校礼堂里找到了避难所。', 'Disaster and Hope', 21, 0, 'senior', 'wordlist', 'required3', 'U6', 'find shelter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'forecast', 'v./n.', '/ˈfɔːkɑːst/', '预测;预报', 'The weather forecast warned that a typhoon was on the way.', '天气预报警告说,一场台风即将来临。', 'Disaster and Hope', 22, 0, 'senior', 'wordlist', 'required3', 'U6', 'the weather forecast', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'announcement', 'n.', '/əˈnaʊnsmənt/', '通告;公告', 'The radio made an announcement telling people to leave at once.', '广播发出公告,叫人们立刻撤离。', 'Disaster and Hope', 23, 0, 'senior', 'wordlist', 'required3', 'U6', 'make an announcement', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'satellite', 'n.', '/ˈsætɪlaɪt/', '人造卫星', 'Today, satellite data helps scientists track every coming storm.', '如今,卫星数据帮助科学家追踪每一场来临的风暴。', 'Disaster and Hope', 24, 0, 'senior', 'wordlist', 'required3', 'U6', 'satellite data', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reliable', 'adj.', '/rɪˈlaɪəbl/', '可信赖的;可靠的', 'For a reliable forecast, it is best to check an official report.', '想要可靠的预报,最好查看官方报告。', 'Disaster and Hope', 25, 0, 'senior', 'wordlist', 'required3', 'U6', 'a reliable forecast', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'precisely', 'adv.', '/prɪˈsaɪsli/', '精确地;准确地', 'Computers now help us predict the weather more precisely than before.', '如今计算机帮助我们比以往更精确地预测天气。', 'Disaster and Hope', 26, 0, 'senior', 'wordlist', 'required3', 'U6', 'predict precisely', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'exceptionally', 'adv.', '/ɪkˈsepʃənəli/', '极其;非常', 'The disaster was caused by exceptionally heavy snow in a short time.', '这场灾难是由短时间内极其大的降雪造成的。', 'Disaster and Hope', 27, 0, 'senior', 'wordlist', 'required3', 'U6', 'exceptionally heavy snow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'immediately', 'adv.', '/ɪˈmiːdiətli/', '即刻;马上', 'When you hear the warning, leave for the shelter immediately.', '听到警报时,立刻前往避难所。', 'Disaster and Hope', 28, 0, 'senior', 'wordlist', 'required3', 'U6', 'act immediately', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'otherwise', 'adv.', '/ˈʌðəwaɪz/', '否则;要不然', 'Do not drink the flood water; otherwise you may get really sick.', '不要喝洪水,否则你可能会病得很重。', 'Disaster and Hope', 29, 0, 'senior', 'wordlist', 'required3', 'U6', 'or otherwise', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nowhere', 'adv.', '/ˈnəʊweə/', '无处;哪里都不', 'Our street had turned into a river, and we were going nowhere.', '我们的街道变成了河流,我们哪儿也去不了。', 'Disaster and Hope', 30, 0, 'senior', 'wordlist', 'required3', 'U6', 'go nowhere', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'grab', 'v.', '/ɡræb/', '抓住;抢夺', 'If birds are flying low, grab your umbrella, for rain may come.', '如果鸟飞得低,抓上你的雨伞,因为可能要下雨了。', 'Disaster and Hope', 31, 0, 'senior', 'wordlist', 'required3', 'U6', 'grab your umbrella', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sufficient', 'adj.', '/səˈfɪʃnt/', '足够的;充足的', 'Make sure you have sufficient food and water before the storm.', '暴风雨来临前,确保你有足够的食物和水。', 'Disaster and Hope', 32, 0, 'senior', 'wordlist', 'required3', 'U6', 'sufficient food and water', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'property', 'n.', '/ˈprɒpəti/', '所有物;财产;资产', 'To protect your property, close the windows and tape them up.', '为保护你的财产,关好窗户并用胶带封好。', 'Disaster and Hope', 33, 0, 'senior', 'wordlist', 'required3', 'U6', 'protect your property', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'helicopter', 'n.', '/ˈhelɪkɒptə/', '直升机', 'Clean drinking water was sent to us by helicopter.', '干净的饮用水是用直升机送给我们的。', 'Disaster and Hope', 34, 0, 'senior', 'wordlist', 'required3', 'U6', 'sent by helicopter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mosquito', 'n.', '/məˈskiːtəʊ/', '蚊子', 'Living in the open air, we were soon bitten by mosquitos.', '住在露天里,我们很快就被蚊子叮咬了。', 'Disaster and Hope', 35, 0, 'senior', 'wordlist', 'required3', 'U6', 'bitten by mosquitos', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'midnight', 'n.', '/ˈmɪdnaɪt/', '午夜;子夜', 'We lay under the midnight sky and looked up at the stars.', '我们躺在午夜的天空下,仰望星星。', 'Disaster and Hope', 36, 0, 'senior', 'wordlist', 'required3', 'U6', 'under the midnight sky', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'county', 'n.', '/ˈkaʊnti/', '县;郡', 'After the rescue, we were taken to a town in a faraway county.', '获救后,我们被带到一个遥远县里的小镇。', 'Disaster and Hope', 37, 0, 'senior', 'wordlist', 'required3', 'U6', 'a faraway county', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lap', 'n.', '/læp/', '(坐着时的)大腿部', 'I was sitting with my cat on my lap when the roof flew off.', '屋顶被掀飞时,我正抱着猫坐在腿上。', 'Disaster and Hope', 38, 0, 'senior', 'wordlist', 'required3', 'U6', 'on my lap', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'plus', 'adj.', '/plʌs/', '(用于数字后)多;以上', 'During the heatwave, the temperature reached thirty degrees plus.', '热浪期间,气温达到了三十多度。', 'Disaster and Hope', 39, 0, 'senior', 'wordlist', 'required3', 'U6', 'thirty degrees plus', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tube', 'n.', '/tjuːb/', '管子;(the Tube)(伦敦)地铁', 'On a hot day, the London Tube can be like a tube full of warm air.', '炎热的日子里,伦敦地铁就像一根装满热空气的管子。', 'Disaster and Hope', 40, 0, 'senior', 'wordlist', 'required3', 'U6', 'the London Tube', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'billion', 'num.', '/ˈbɪljən/', '十亿', 'The hurricane caused billions of dollars in damage.', '这场飓风造成了数十亿美元的损失。', 'Disaster and Hope', 41, 0, 'senior', 'wordlist', 'required3', 'U6', 'billions in damage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'donate', 'v.', '/dəʊˈneɪt/', '捐赠;捐献', 'Many people donated money and food to help the flood victims.', '许多人捐钱捐物来帮助洪灾受灾者。', 'Disaster and Hope', 42, 0, 'senior', 'wordlist', 'required3', 'U6', 'donate money and food', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'aid', 'n./v.', '/eɪd/', '援助;帮助', 'Rescue teams from many countries came to aid the injured.', '来自许多国家的救援队前来援助伤员。', 'Disaster and Hope', 43, 0, 'senior', 'wordlist', 'required3', 'U6', 'send aid', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'survive', 'v.', '/səˈvaɪv/', '幸存;生存下来', 'Being prepared is the best way to survive a disaster.', '做好准备是在灾难中幸存下来的最好办法。', 'Disaster and Hope', 44, 0, 'senior', 'wordlist', 'required3', 'U6', 'survive the disaster', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rebuild', 'v.', '/ˌriːˈbɪld/', '重建;再建', 'A year later, the families were working together to rebuild their homes.', '一年后,这些家庭正齐心协力重建家园。', 'Disaster and Hope', 45, 0, 'senior', 'wordlist', 'required3', 'U6', 'rebuild our homes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'positive', 'adj.', '/ˈpɒzətɪv/', '积极的;乐观的', 'It was hard, but Mom told us to stay positive and see the good side.', '尽管艰难,妈妈仍叫我们保持乐观,看到好的一面。', 'Disaster and Hope', 46, 0, 'senior', 'wordlist', 'required3', 'U6', 'stay positive', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'guideline', 'n.', '/ˈɡaɪdlaɪn/', '指导原则;指导方针', 'Read these safety guidelines so that your family can stay safe.', '阅读这些安全指南,好让你的家人保持安全。', 'Disaster and Hope', 47, 0, 'senior', 'wordlist', 'required3', 'U6', 'safety guidelines', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'damage', 'n./v.', '/ˈdæmɪdʒ/', '损害;破坏', 'The storm caused great damage to homes and roads.', '这场风暴对房屋和道路造成了巨大破坏。', 'Disaster and Hope', 48, 0, 'senior', 'wordlist', 'required3', 'U6', 'cause great damage', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u6.01', '①状语从句中省略「主语+be」(when/while/if/though/once/unless + 分词或形容词)', 'A2', 10, '外研社版必修第三册 U6 — 当状语从句的主语与主句主语一致时,可省去从句的「主语+be」,只留下 -ing(主动)/ -ed(被动)/ 形容词。判断:从句动作是主语主动发出用 -ing,被动承受用 -ed。', 1, 'required3', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u6.02', '②并列与比较结构中省略重复动词(留下助动词/操作词)', 'A2', 10, '外研社版必修第三册 U6 — 并列句和 so/neither/nor/than/as/but 后,常省去与前面重复的动词(短语),只保留一个助动词或情态动词来代替;这个助动词要与原动词的时态、人称一致。', 2, 'required3', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u6.03', '③不定式省略(只留 to)与对话中的省略', 'A2', 10, '外研社版必修第三册 U6 — 在 love/like/want/have/hope/try/able 等之后,可省去重复的动词原形,只保留不定式符号 to;在口语应答中也常省去重复的动词短语,只留一个助动词/情态动词。', 3, 'required3', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"When ____ about the coming typhoon, the villagers quickly moved to higher ground."', 'warned', 'warning', 'warn', 'to warn', 'A', '从句主语 = villagers,他们是「被警告」,省略 they were 后留下被动的 -ed 形式 warned。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"While ____ for the rescue boat, we shared the little water we had."', 'waited', 'waiting', 'wait', 'to wait', 'B', '从句主语 = we,主动「等待」,省略 we were 后留下 -ing 形式 waiting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Though ____ of the danger, the firefighters still rushed into the building."', 'awareness', 'awarely', 'aware', 'to aware', 'C', 'though they were aware 省略「主语+be」后留下形容词 aware。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"If ____ in time, a warning can save thousands of lives."', 'sending', 'sends', 'to send', 'sent', 'D', 'warning 是「被送出」,省略 it is 后留下被动 -ed 形式 sent。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Once ____, the wildfire spread across the dry hills within hours."', 'started', 'starting', 'starts', 'to start', 'A', 'wildfire 是「被点燃/被引发」,省略 it was 后留下被动 -ed 形式 started。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"When ____ how to stay safe, children usually listen very carefully."', 'telling', 'told', 'tell', 'to tell', 'B', 'children 是「被告知」,省略 they are 后留下被动 -ed 形式 told。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"While ____ through the ruined town, the reporter could not hold back her tears."', 'walked', 'walks', 'walking', 'to walk', 'C', 'reporter 主动「行走」,省略 she was 后留下 -ing 形式 walking。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Unless ____ at once, the injured man might not survive the night."', 'treating', 'treats', 'to treat', 'treated', 'D', 'man 是「被救治」,省略 he is 后留下被动 -ed 形式 treated。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Though ____ from the long search, the rescuers refused to rest."', 'exhausted', 'exhausting', 'exhaust', 'to exhaust', 'A', 'rescuers「感到精疲力竭」,省略 they were 后留下形容词化的 -ed 形式 exhausted。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"When ____ by helicopter, the survivors finally felt safe."', 'rescuing', 'rescued', 'rescue', 'to rescue', 'B', 'survivors 是「被营救」,省略 they were 后留下被动 -ed 形式 rescued。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"If ____ correctly, the warning system can give people enough time to leave."', 'using', 'uses', 'used', 'to use', 'C', 'system 是「被使用」,省略 it is 后留下被动 -ed 形式 used。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"While ____ to the forecast on the radio, we packed our emergency bags."', 'listened', 'listens', 'to listen', 'listening', 'D', 'we 主动「收听」,省略 we were 后留下 -ing 形式 listening。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Once ____, the announcement was repeated on every radio station in the area."', 'made', 'making', 'makes', 'to make', 'A', 'announcement 是「被发布」,省略 it was 后留下被动 -ed 形式 made。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Though ____ for many hours, the rescue dogs did not give up."', 'worked', 'working', 'works', 'to work', 'B', 'dogs 主动「工作」,省略 they had been 后留下 -ing 形式 working。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"When ____ with a serious crisis, a calm leader is very important."', 'facing', 'faces', 'faced', 'to face', 'C', 'be faced with 「面临」,人是被动一方,省略后留下 -ed 形式 faced。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"If ____ early enough, a small fire can be put out quite easily."', 'noticing', 'notices', 'to notice', 'noticed', 'D', 'fire 是「被发现」,省略 it is 后留下被动 -ed 形式 noticed。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"While ____ in the shelter, the children drew pictures to stay calm."', 'staying', 'stayed', 'stays', 'to stay', 'A', 'children 主动「待在」,省略 they were 后留下 -ing 形式 staying。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Though ____ by the disaster, the town slowly came back to life."', 'shaking', 'shaken', 'shakes', 'to shake', 'B', 'town 是「被震撼/被冲击」,省略 it was 后留下被动 -ed 形式 shaken。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"Unless ____ carefully, the old houses may collapse in the next quake."', 'repairing', 'repairs', 'repaired', 'to repair', 'C', 'houses 是「被修理」,省略 they are 后留下被动 -ed 形式 repaired。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.01'), '"When ____ for advice, the experts always mention having an escape plan."', 'asking', 'asks', 'to ask', 'asked', 'D', 'experts 是「被询问」,省略 they are 后留下被动 -ed 形式 asked。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"The earthquake destroyed the school, and so ____ the old library."', 'did', 'does', 'was', 'had', 'A', '前句动词 destroyed 是一般过去时,so 后省略重复动词、用过去时助动词 did 代替。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"My parents did not panic during the storm, and neither ____ I."', 'do', 'did', 'was', 'have', 'B', '前句一般过去时,neither 后倒装并省略动词,用 did 代替。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"She has already packed enough food, but her brother ____ not."', 'does', 'did', 'has', 'is', 'C', '前句现在完成时 has packed,省略重复动词后保留与之一致的 has。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"The rescue team worked far harder than anyone ____ imagined."', 'has', 'was', 'does', 'had', 'D', 'than 后接的是先于过去发生的「想象」,与过去时主句相比用过去完成助动词 had imagined。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"He reacted to the warning much faster than his sister ____."', 'did', 'was', 'had', 'does', 'A', '比较从句省略重复的 reacted,用过去时助动词 did 代替。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"I can''t reach the shelter on foot, and my grandmother ____, either."', 'doesn''t', 'can''t', 'isn''t', 'won''t', 'B', '前句用情态动词 can''t,省略重复动词后保留 can''t。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"They lost their home in the flood, and so ____ we."', 'were', 'had', 'did', 'do', 'C', '前句一般过去时 lost,so 后省略动词、用 did 代替。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"This forecast is far more reliable than the last one ____."', 'did', 'has', 'does', 'was', 'D', '比较的是过去那次预报「(可靠)是」,系动词省略后保留过去时 was。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"Helen survived the avalanche, and so ____ her dog."', 'did', 'was', 'had', 'does', 'A', '前句一般过去时 survived,so 后用 did 代替重复动词。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"We had not heard the announcement, and neither ____ our neighbours."', 'did', 'had', 'were', 'have', 'B', '前句过去完成时 had not heard,neither 后保留 had。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"She will help rebuild the homes, and so ____ her classmates."', 'do', 'are', 'will', 'did', 'C', '前句一般将来时 will help,so 后省略动词、保留 will。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"The storm caused much more damage this year than it ____ last year."', 'does', 'was', 'had', 'did', 'D', '比较从句省略重复的 caused,用过去时助动词 did 代替。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"I am not afraid of typhoons now, but my little sister still ____."', 'is', 'does', 'has', 'did', 'A', '前句用系动词 am(afraid),省略 afraid 后保留与之一致的 is。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"They prepared for the flood far more carefully than we ____."', 'were', 'did', 'are', 'had', 'B', '比较从句省略重复的 prepared,用过去时助动词 did 代替。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"He has rebuilt his house already, and his neighbours ____ too."', 'has', 'did', 'have', 'are', 'C', '前句现在完成时,主语 neighbours 为复数,省略动词后保留 have。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"We didn''t get any warning, and the next village ____, either."', 'wasn''t', 'hasn''t', 'won''t', 'didn''t', 'D', '前句一般过去时否定 didn''t get,省略动词后保留 didn''t。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"The flood rose much faster than the rescuers ____ expected."', 'had', 'has', 'were', 'did', 'A', 'than 后是先于过去的「预料」,用过去完成助动词 had expected。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"She can swim to safety, but the old man next door ____."', 'doesn''t', 'can''t', 'isn''t', 'hasn''t', 'B', '前句用 can,转折后表示「不能」,省略动词后保留 can''t。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"Our town received emergency aid, and so ____ the nearby county."', 'was', 'has', 'did', 'does', 'C', '前句一般过去时 received,so 后用 did 代替重复动词。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.02'), '"I have never seen such a terrible storm, and neither ____ my grandfather."', 'did', 'was', 'have', 'has', 'D', '前句现在完成时 have never seen,主语 grandfather 为第三人称单数,neither 后保留 has。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Would you like to join the rescue team?"  B: "Yes, I''d love ____."', 'to', 'to do', 'doing', 'do', 'A', '为避免重复 join the rescue team,只保留不定式符号 to,即 I''d love to。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"I didn''t want to leave my home, but in the end I had ____."', 'to do', 'to', 'doing', 'done', 'B', 'have to 后省略重复的 leave my home,只留 to。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"You don''t need to stay outside in the storm if you don''t want ____."', 'to do', 'doing', 'to', 'do', 'C', 'want 后省略 stay outside,只保留不定式符号 to。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"She hoped to find her lost cat, and in the end she was lucky enough ____."', 'to do', 'doing', 'for', 'to', 'D', 'enough 后省略 find her cat,只留 to。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"He never expected to survive the flood, but somehow he managed ____."', 'to', 'to do', 'doing', 'do', 'A', 'manage 后省略 survive the flood,只保留不定式符号 to。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"We can rebuild the school together if we really want ____."', 'to do', 'to', 'doing', 'do', 'B', 'want 后省略 rebuild the school,只留 to。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"I''d help carry the water bottles, but I''m just not strong enough ____."', 'to do', 'doing', 'to', 'for', 'C', 'enough 后省略 carry the bottles,只保留 to。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"They asked us to donate some clothes, and we were very glad ____."', 'to do', 'doing', 'do', 'to', 'D', 'glad 后省略 donate some clothes,只留不定式符号 to。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"I tried to call for help during the storm, but I just wasn''t able ____."', 'to', 'to do', 'doing', 'do', 'A', 'be able 后省略 call for help,只保留 to。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"Nobody forced him to volunteer; he chose ____ all by himself."', 'to do', 'to', 'doing', 'do', 'B', 'choose 后省略 volunteer,只留不定式符号 to。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Will the new satellites help us forecast the typhoon?"  B: "Yes, they ____."', 'are', 'do', 'will', 'have', 'C', '应答省略 help us forecast the typhoon,保留与问句一致的助动词 will。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Have the rescue teams reached the village yet?"  B: "No, they ____ yet."', 'didn''t', 'aren''t', 'won''t', 'haven''t', 'D', '问句用现在完成时 have reached,应答省略动词后保留 haven''t。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Did many families lose their homes?"  B: "Yes, thousands of them ____."', 'did', 'do', 'were', 'had', 'A', '问句一般过去时 did lose,应答省略动词后保留 did。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Could you hear the emergency announcement?"  B: "No, I ____."', 'didn''t', 'couldn''t', 'wasn''t', 'haven''t', 'B', '问句用情态动词 could,应答省略 hear the announcement 后保留 couldn''t。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Should we leave before the storm arrives?"  B: "Yes, we ____."', 'will', 'are', 'should', 'do', 'C', '问句用情态动词 should,应答省略 leave 后保留 should。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Are the roads still flooded?"  B: "Some ____, some aren''t."', 'do', 'have', 'were', 'are', 'D', '问句用 are flooded,应答省略 flooded 后保留 are。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Do you think the old bridge will hold?"  B: "I''m afraid it ____."', 'won''t', 'doesn''t', 'isn''t', 'hasn''t', 'A', '谈论将来 will hold,表否定时省略 hold 后保留 won''t。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), 'A: "Were you frightened during the earthquake?"  B: "Yes, I ____."', 'did', 'was', 'were', 'had', 'B', '问句用系动词 were frightened,应答省略 frightened 后保留与「I」一致的 was。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"You may go to the shelter now if you''d like ____."', 'to do', 'doing', 'to', 'do', 'C', 'would like 后省略 go to the shelter,只保留不定式符号 to。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U6' AND code='f3u6.03'), '"She used to fear every storm, but these days she doesn''t seem ____ any more."', 'to do', 'doing', 'do', 'to', 'D', 'seem 后省略 fear every storm,只留不定式符号 to。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Hot Day on the Tube', 'Picking up a free newspaper at the station, I read the title "Hot! Hot! Hot!". Today the temperature in London is expected to reach thirty degrees plus, though the usual high for July is only twenty-two. It is going to be awful on the Tube, because the oldest line has no air conditioning at all. Going down the stairs feels like jumping into a hot oven. Inside the train it is even worse, and the passenger next to me and I seem to be melting into one. Reading on, I am shocked by photos of a hurricane in Asia and forest fires across Southern Europe. Experts say such bad weather happens more often because of climate change, and the news makes me feel nervous. But stepping out at last, I feel a fresh wind on my face and decide that, after all, thirty degrees is not the end of the world.', '记叙·伦敦地铁里的热浪', 151, '[{"q":"Why is the journey on the Tube so uncomfortable that day?","answer":"A","options":["The train runs on a very old line with no cooling on a baking hot day.","The train is completely empty and quiet.","There is a flood inside the station.","The newspaper costs too much money."],"explanation":"原文说最老的线路没有空调、车厢里更热,故是高温加无空调,为转述。"},{"q":"How does the newspaper make the writer feel?","answer":"B","options":["Calm and sleepy.","Worried about extreme weather around the world.","Proud of the weather in London.","Excited about a holiday by the sea."],"explanation":"报上飓风、森林大火的照片让作者感到紧张不安,为概括转述。"},{"q":"What does the writer realise at the end of the trip?","answer":"A","options":["The hot day is not as terrible as he feared.","The Tube will close forever.","He should move to another country.","Climate change is not real."],"explanation":"走出车站感到凉风,觉得三十度并非世界末日,为末段转述。"}]'::jsonb, '[{"word":"plus","cn":"(数字后)多"},{"word":"climate change","cn":"气候变化"},{"word":"air conditioning","cn":"空调"}]'::jsonb, 2, 'required3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Stars After the Storm', 'It all happened so quickly. I was sitting with my cat on my lap when the roof simply flew off, and suddenly there was sky above me. Our street turned into a river in seconds, and we were going nowhere. Without a roof, staying inside was dangerous, and the only clean water we had was sent to us by helicopter. It was never quite enough. Living in the open air, we soon became dinner for the mosquitos. But Mom kept telling us to stay positive and to look for the good side of things. We had lost almost everything, yet we were all together and safe. I still remember us lying under the midnight sky, looking up at the stars. Because there were no city lights, we could see the Milky Way clearly. Even though we had lost so much, moments like those gave us hope, and a year later we were back home, working hard to rebuild our lives.', '记叙·飓风之后的希望', 160, '[{"q":"What happened to the family''s home during the storm?","answer":"B","options":["It was sold to a neighbour.","Its roof was blown away and the street flooded.","It was moved to a faraway county.","It stayed completely dry and safe."],"explanation":"屋顶被掀飞、街道变成河流,为对原文细节的转述。"},{"q":"What did Mom keep encouraging the family to do?","answer":"C","options":["Leave the cat behind.","Stop talking to each other.","Keep a positive attitude and look on the bright side.","Drink the dirty flood water."],"explanation":"妈妈让大家保持乐观、看到好的一面,为转述。"},{"q":"Why were the stars so clear at night?","answer":"D","options":["Because the moon was very bright.","Because they used a telescope.","Because the sky was full of clouds.","Because the city''s lights had all gone out."],"explanation":"因没有城市灯光,银河才看得清楚,为对原文的转述。"}]'::jsonb, '[{"word":"lap","cn":"(坐着时的)大腿部"},{"word":"positive","cn":"积极乐观的"},{"word":"rebuild","cn":"重建"}]'::jsonb, 2, 'required3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'China''s Rescue in Nepal', 'The powerful earthquake that hit Nepal in April 2015 was one of the worst in history. As soon as the news came out, China was quick to start organising emergency aid for the country. International rescue teams soon began to arrive, and among all the heavy rescue teams, the China International Search and Rescue Team was the very first to reach the disaster area. The team was made up of sixty-two people. It included not only rescuers and medical staff but also earthquake experts who understood how buildings fall. They searched the ruins day and night, hoping to find anyone still alive. By early May, China had donated emergency aid worth millions of dollars, with even more help on the way. Stories like this remind us that, when one country faces a terrible disaster, help often comes quickly from friends far across the world, and that kindness can shine brightly even in the darkest hour.', '说明·中国赴尼泊尔地震救援', 155, '[{"q":"What did China do as soon as the earthquake news arrived?","answer":"A","options":["It began to organise emergency help straight away.","It waited for several months to react.","It asked Nepal to send help instead.","It closed its own borders."],"explanation":"消息一出中国立刻着手组织紧急援助,为转述。"},{"q":"Who were part of the Chinese rescue team?","answer":"B","options":["Only one famous doctor.","Rescuers, medical staff and earthquake experts.","A group of tourists.","Only news reporters."],"explanation":"队伍由救援人员、医护人员和地震专家组成,为转述。"},{"q":"What is the main message of the passage?","answer":"C","options":["Earthquakes never cause much harm.","Rescue work is always easy and quick.","Help and kindness can come from far away in a disaster.","Only Nepal can solve its own problems."],"explanation":"末段强调灾难中远方的帮助与善意,为主旨转述。"}]'::jsonb, '[{"word":"emergency aid","cn":"紧急援助"},{"word":"rescue team","cn":"救援队"},{"word":"ruins","cn":"废墟"}]'::jsonb, 2, 'required3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'When Animals Warn Us', 'Technology is not the only way to guess what the weather will do. Nature has its own ways, too. Unusual animal behaviour, for example, can tell us whether cold, wet weather or a hot, dry period is coming. If fish are jumping higher than usual, or frogs are calling more loudly, it may soon rain. Next time you look up at the sky, do not only watch for rain clouds; watch the birds as well. If they are flying low, it is wise to grab your umbrella. People also say that mice and snakes move to safer, higher ground several days before an earthquake, while dogs that avoid the beach may be warning of a coming tsunami. Of course, although these signs may suggest that something bad is on the way, they cannot tell us exactly when or where it will happen. So, for an accurate and reliable warning, it is still best to check an official, scientific report.', '说明·动物如何预示天气', 159, '[{"q":"According to the passage, what might mean rain is coming soon?","answer":"D","options":["Birds singing in the morning.","Dogs sleeping all day.","Snakes staying underground.","Fish jumping high or frogs calling loudly."],"explanation":"鱼跳高、青蛙叫得响可能预示要下雨,为转述。"},{"q":"What may dogs avoiding the beach be a sign of?","answer":"A","options":["An approaching tsunami.","A coming holiday.","A drop in food prices.","A new building project."],"explanation":"狗避开海滩可能预示海啸将至,为对原文的转述。"},{"q":"Why does the writer still suggest checking an official report?","answer":"B","options":["Because animals are usually wrong.","Because animal signs cannot give the exact time or place.","Because reports are cheaper than animals.","Because nobody believes scientists."],"explanation":"动物迹象说不清确切时间地点,故需可靠的官方报告,为转述。"}]'::jsonb, '[{"word":"behaviour","cn":"行为"},{"word":"grab","cn":"抓住"},{"word":"reliable","cn":"可靠的"}]'::jsonb, 2, 'required3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Disasters in History', 'History is full of natural disasters that people still remember today. In 1960, Chile suffered the strongest earthquake ever recorded. It set off a tsunami with waves as high as twenty-five metres, and these waves reached places as far away as Hawaii and Japan. In February 1972, an exceptionally cold blizzard struck Iran. Winter storms brought almost eight metres of snow to the south of the country, and about four thousand people lost their lives. In the Alps, the winter of 1950 became known as the Winter of Terror, when more than six hundred avalanches struck mountain towns within a short time, destroying buildings and claiming many lives. East Africa, by contrast, faced the opposite problem in 2011: a terrible drought, said to be the worst in sixty years, during which almost no rain fell for a whole year. It led to a severe food crisis that threatened the lives of millions of people across the region.', '说明·历史上著名的自然灾难', 157, '[{"q":"What did the 1960 Chile earthquake lead to?","answer":"C","options":["A long period of drought.","A series of avalanches in the Alps.","A huge tsunami that reached far-off countries.","A drop in the sea level."],"explanation":"智利地震引发了远及夏威夷、日本的海啸,为转述。"},{"q":"Why is the winter of 1950 in the Alps remembered?","answer":"D","options":["Because it was unusually warm.","Because there was no snow at all.","Because a volcano erupted there.","Because hundreds of avalanches hit mountain towns."],"explanation":"那年冬天数百次雪崩袭击山城,被称为恐怖之冬,为转述。"},{"q":"What problem did East Africa face in 2011?","answer":"A","options":["A long drought that caused a food crisis.","Too much snow.","A powerful earthquake.","A sudden flood."],"explanation":"东非遭遇严重干旱,引发粮食危机,为转述。"}]'::jsonb, '[{"word":"exceptionally","cn":"极其"},{"word":"claim (lives)","cn":"夺去(生命)"},{"word":"crisis","cn":"危机"}]'::jsonb, 2, 'required3', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Be Ready for a Flood', 'Many people have no idea what to do when a disaster suddenly strikes. Being well prepared, however, is the best way to increase your chances of staying safe. Here are some simple guidelines for floods, a common threat to towns near rivers and the coast. Before a flood, protect your property by closing the windows and moving anything valuable to a higher floor. Make sure that you have sufficient food, clean water, medicine and batteries, and agree on a meeting place with your family in case you are separated. During a flood, listen carefully to weather warnings and the latest announcements. Move to higher ground immediately, and never try to walk or drive through fast-moving water, because even shallow water can knock you off your feet. Do not drink the flood water; otherwise you may become very sick. Finally, do not assume the danger has passed just because the rain has stopped, as more water may still be on the way.', '应用·洪水来临前后的安全指南', 161, '[{"q":"What should you do with valuable things before a flood?","answer":"B","options":["Leave them outside the house.","Move them up to a higher floor.","Throw them into the river.","Give them all away."],"explanation":"灾前把贵重物品搬到更高楼层以保护财产,为转述。"},{"q":"Why should you not walk or drive through fast-moving water?","answer":"C","options":["Because it is too clean.","Because it is always frozen.","Because moving water can sweep a person off their feet, even when it is not deep.","Because it makes the car faster."],"explanation":"即使浅水也能把人冲倒,故不要涉水,为转述。"},{"q":"What mistake does the passage warn people not to make?","answer":"D","options":["Talking to their family.","Listening to weather warnings.","Storing food and water.","Thinking the danger is over just because the rain stops."],"explanation":"不要因雨停就认为危险已过,为末段转述。"}]'::jsonb, '[{"word":"guideline","cn":"指导原则"},{"word":"sufficient","cn":"足够的"},{"word":"property","cn":"财产"}]'::jsonb, 2, 'required3', 'U6', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U6', 'A Day as a Flood Volunteer', 'Last summer, heavy rain caused a terrible (1)____ in our town, and the river rose over its banks. I decided to (2)____ as a volunteer to help my neighbours. Early each morning, we filled bags with sand to (3)____ back the water. The work was hard, and by the (4)____ of each day we were tired and wet. Many families had lost their homes and had (5)____ to go, so we gave them food and a dry place to (6)____. One old man kept thanking us, even though he had lost almost everything he (7)____. Helping others made me feel that even a small action could bring people (8)____. By the end of the week, the water had begun to (9)____, and people slowly returned to clean their houses. I learned that a disaster can be terrible, but it can also (10)____ out the kindness in ordinary people.', 148, 2, '[{"q":"1","answer":"A","options":["flood","drought","forest","garden"],"explanation":"heavy rain caused a flood 暴雨引发洪水。"},{"q":"2","answer":"B","options":["sleep","work","wait","shop"],"explanation":"work as a volunteer 当志愿者。"},{"q":"3","answer":"C","options":["throw","sell","hold","lose"],"explanation":"hold back the water 挡住水。"},{"q":"4","answer":"D","options":["start","top","side","end"],"explanation":"by the end of each day 到每天结束时。"},{"q":"5","answer":"A","options":["nowhere","everywhere","something","anyone"],"explanation":"had nowhere to go 无处可去。"},{"q":"6","answer":"B","options":["cry","stay","buy","win"],"explanation":"a dry place to stay 待的干燥地方。"},{"q":"7","answer":"C","options":["forgot","sold","owned","threw"],"explanation":"everything he owned 他拥有的一切。"},{"q":"8","answer":"D","options":["noise","money","fear","hope"],"explanation":"bring people hope 给人希望。"},{"q":"9","answer":"A","options":["fall","rise","burn","grow"],"explanation":"the water began to fall 水开始退去。"},{"q":"10","answer":"B","options":["take","bring","put","give"],"explanation":"bring out the kindness 带出善意。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U6', 'Our Family Emergency Plan', 'After watching the news about a big (1)____, my family decided to make an emergency plan. First, we packed a special bag with (2)____ food, clean water and a torch in case the power went out. My dad said we should also keep some (3)____ in it, because someone might get hurt. Next, we agreed on a safe (4)____ where we would all meet if we were separated during a disaster. My mum wrote down important phone numbers so that we could (5)____ for help quickly. We also learned to turn off the gas and water (6)____, to stop a fire or a flood from getting worse. My little sister was a bit (7)____ at first, but making the plan together actually helped her feel (8)____. Now, whenever a storm is (9)____ on the news, we know exactly what to do. Being prepared, my dad always says, is the best way to stay (10)____.', 154, 2, '[{"q":"1","answer":"C","options":["holiday","concert","disaster","market"],"explanation":"news about a big disaster 关于大灾难的新闻。"},{"q":"2","answer":"D","options":["empty","loud","old","extra"],"explanation":"extra food 额外的食物。"},{"q":"3","answer":"A","options":["medicine","music","sugar","paint"],"explanation":"keep some medicine 备些药品。"},{"q":"4","answer":"B","options":["price","place","song","game"],"explanation":"a safe place to meet 安全的会合地点。"},{"q":"5","answer":"C","options":["sleep","sing","call","pay"],"explanation":"call for help 呼救。"},{"q":"6","answer":"D","options":["slowly","quietly","happily","immediately"],"explanation":"turn off ... immediately 立刻关掉。"},{"q":"7","answer":"A","options":["afraid","proud","glad","calm"],"explanation":"a bit afraid at first 起初有点害怕。"},{"q":"8","answer":"B","options":["worse","safer","colder","louder"],"explanation":"helped her feel safer 让她感到更安全。"},{"q":"9","answer":"C","options":["leaving","sleeping","coming","swimming"],"explanation":"a storm is coming 风暴将至。"},{"q":"10","answer":"D","options":["late","busy","rich","safe"],"explanation":"the best way to stay safe 保持安全的最好办法。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U6', 'Max the Rescue Dog', 'Max is not an ordinary dog; he is a trained (1)____ dog who works with a mountain team. When an avalanche (2)____ down a slope, people can be buried deep under the snow, and every minute (3)____. Max can smell a person even through a thick (4)____ of snow, something no machine can do so well. Last winter, after a heavy (5)____, two climbers went missing on the mountain. The rescue team could find (6)____ at first, and they were slowly losing hope. Then Max suddenly began to (7)____ at one spot and dug quickly with his paws. Below the snow, the climbers were cold but still (8)____. Thanks to Max, both of them were (9)____ in time. The team says a good rescue dog like Max is far more (10)____ than the most expensive machine they own.', 138, 2, '[{"q":"1","answer":"A","options":["rescue","garden","music","farm"],"explanation":"a rescue dog 救援犬。"},{"q":"2","answer":"B","options":["sings","rushes","sleeps","waits"],"explanation":"an avalanche rushes down 雪崩冲下。"},{"q":"3","answer":"C","options":["sleeps","sells","counts","buys"],"explanation":"every minute counts 每分钟都很关键。"},{"q":"4","answer":"D","options":["glass","box","door","layer"],"explanation":"a thick layer of snow 厚厚一层雪。"},{"q":"5","answer":"A","options":["blizzard","holiday","lesson","meal"],"explanation":"after a heavy blizzard 一场大暴风雪后。"},{"q":"6","answer":"B","options":["everybody","nobody","someone","anyone"],"explanation":"could find nobody 一个人也找不到。"},{"q":"7","answer":"C","options":["swim","read","bark","cook"],"explanation":"began to bark 开始吠叫。"},{"q":"8","answer":"D","options":["asleep","angry","empty","alive"],"explanation":"cold but still alive 寒冷但仍活着。"},{"q":"9","answer":"A","options":["rescued","forgotten","sold","lost"],"explanation":"were rescued in time 被及时救出。"},{"q":"10","answer":"B","options":["boring","useful","heavy","quiet"],"explanation":"more useful than the machine 比机器更有用。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U6', 'Trapped by a Blizzard', 'One December, an exceptionally heavy (1)____ hit our small mountain village without much warning. Within hours, the snow was so deep that the only road out was completely (2)____. We were trapped, and the electricity soon went (3)____ as well. My grandmother stayed calm and told us not to (4)____. We kept warm around the fire and made our food (5)____, eating only a little at each meal. Outside, the wind was so strong that we could see (6)____ through the windows. On the third day, we heard the sound of a (7)____ flying low above the village. The pilot had spotted our smoke and dropped boxes of food and (8)____ down to us. Everyone cheered and waved. Two days later, a team finally (9)____ the snow on the road, and help arrived. That winter taught me how quickly nature can change our lives, and how important it is to stay (10)____ together.', 153, 2, '[{"q":"1","answer":"C","options":["drought","summer","blizzard","market"],"explanation":"a heavy blizzard hit 一场大暴风雪袭来。"},{"q":"2","answer":"D","options":["open","clean","free","blocked"],"explanation":"the road was blocked 道路被堵。"},{"q":"3","answer":"A","options":["off","up","on","in"],"explanation":"the electricity went off 停电了。"},{"q":"4","answer":"B","options":["sing","panic","eat","sleep"],"explanation":"told us not to panic 叫我们别慌。"},{"q":"5","answer":"C","options":["sell","grow","last","buy"],"explanation":"made our food last 让食物撑得更久。"},{"q":"6","answer":"D","options":["everything","someone","anyone","nothing"],"explanation":"could see nothing 什么都看不见。"},{"q":"7","answer":"A","options":["helicopter","bicycle","train","boat"],"explanation":"a helicopter flying low 低飞的直升机。"},{"q":"8","answer":"B","options":["sand","medicine","paper","toys"],"explanation":"food and medicine 食物和药品。"},{"q":"9","answer":"C","options":["sold","painted","cleared","grew"],"explanation":"cleared the snow 清除积雪。"},{"q":"10","answer":"D","options":["quiet","late","busy","close"],"explanation":"stay close together 紧紧靠在一起。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U6', 'Rebuilding After the Fire', 'Two years ago, a terrible (1)____ swept through the forest near our town and burned hundreds of homes. When the fire was finally (2)____, many families had lost everything they owned. At first, people felt (3)____ and did not know where to begin. But slowly, neighbours started to help one another (4)____ their houses. Builders gave their time for free, and people from other towns (5)____ money, clothes and furniture. My own family received a warm blanket from a stranger, with a short note that said, "Don''t give up (6)____." Those few words gave us real (7)____. Little by little, new walls and roofs began to (8)____ where the burned houses had stood. A year later, our street looked almost (9)____ again. The fire had taken so much from us, yet it also showed us how (10)____ people can be when they work together.', 144, 2, '[{"q":"1","answer":"A","options":["wildfire","flood","blizzard","drought"],"explanation":"a wildfire swept through the forest 山火席卷森林。"},{"q":"2","answer":"B","options":["in","out","up","on"],"explanation":"the fire was finally out 火终于熄灭。"},{"q":"3","answer":"C","options":["proud","happy","lost","calm"],"explanation":"felt lost 感到不知所措。"},{"q":"4","answer":"D","options":["sell","paint","leave","rebuild"],"explanation":"help one another rebuild 互相帮忙重建。"},{"q":"5","answer":"A","options":["donated","wasted","burned","hid"],"explanation":"donated money and clothes 捐钱捐衣。"},{"q":"6","answer":"B","options":["money","hope","time","space"],"explanation":"don''t give up hope 别放弃希望。"},{"q":"7","answer":"C","options":["trouble","noise","comfort","fear"],"explanation":"gave us real comfort 给我们真正的安慰。"},{"q":"8","answer":"D","options":["fall","burn","melt","appear"],"explanation":"began to appear 开始出现。"},{"q":"9","answer":"A","options":["normal","empty","dark","wet"],"explanation":"looked almost normal 看起来几乎恢复正常。"},{"q":"10","answer":"B","options":["lazy","kind","rude","quiet"],"explanation":"how kind people can be 人们能多么善良。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U6', 'A Tsunami Drill That Worked', 'Our seaside town lies close to the ocean, so we know that a (1)____ is always a possible danger. Every year, the school holds a special (2)____ to teach students what to do if huge waves come. When the alarm (3)____, we must leave the classroom calmly and walk quickly to the high hill behind the school. Last spring, this practice suddenly became (4)____. One afternoon, the ground shook with a strong (5)____, and minutes later the warning sirens began to sound. Because we had practised so many times, nobody (6)____. Teachers led us up the hill (7)____, just as we had learned. From the top, we watched as large waves rushed over the empty beach below. Not a single person was (8)____, because everyone had reached safety in time. That day, our whole town understood why such (9)____ matter so much. A little preparation, our head teacher said, had (10)____ many lives.', 153, 2, '[{"q":"1","answer":"C","options":["drought","wildfire","tsunami","blizzard"],"explanation":"close to the ocean, a tsunami is a danger 海啸是危险。"},{"q":"2","answer":"D","options":["party","exam","concert","drill"],"explanation":"a special drill 一次特别的演练。"},{"q":"3","answer":"A","options":["rings","sleeps","sings","eats"],"explanation":"when the alarm rings 警报响起时。"},{"q":"4","answer":"B","options":["easy","real","funny","boring"],"explanation":"the practice became real 演练变成了真的。"},{"q":"5","answer":"C","options":["wind","smile","earthquake","song"],"explanation":"shook with a strong earthquake 强烈地震使地面摇动。"},{"q":"6","answer":"D","options":["laughed","slept","sang","panicked"],"explanation":"nobody panicked 没人惊慌。"},{"q":"7","answer":"A","options":["calmly","loudly","angrily","sleepily"],"explanation":"led us up the hill calmly 镇定地带我们上山。"},{"q":"8","answer":"B","options":["late","hurt","busy","rich"],"explanation":"not a single person was hurt 无一人受伤。"},{"q":"9","answer":"C","options":["games","prices","drills","songs"],"explanation":"why such drills matter 这样的演练为何重要。"},{"q":"10","answer":"D","options":["lost","sold","wasted","saved"],"explanation":"had saved many lives 挽救了许多生命。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·对话 Getting Ready for the Typhoon', '外研社版必修第三册 U6 · dialogue', 3, 'Lily: Have you heard the news, Sam? A strong typhoon is coming tonight.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 How a Tsunami Forms', '外研社版必修第三册 U6 · passage', 2, 'A tsunami is one of the most dangerous events in the sea.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·对话 An Earthquake Survivor''s Story', '外研社版必修第三册 U6 · dialogue', 3, 'Anna: Mr Li, can you tell us what you remember about the earthquake?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 Forecasting with Satellites', '外研社版必修第三册 U6 · passage', 2, 'For thousands of years, people have tried to predict the weather.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·对话 A Call About the Heatwave', '外研社版必修第三册 U6 · dialogue', 3, 'Mr Brown: Hello, I''m calling to check how long this heatwave will last.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 A Message of Hope', '外研社版必修第三册 U6 · passage', 2, 'When a disaster strikes, it can take away our homes, but it cannot take away our courage.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write Flood Safety Guidelines(写一份洪水安全指南)', 'Flood Safety Guidelines', '假设你是学校广播站成员,最近你们地区进入雨季,常有洪水威胁。请用英语写一份约80词的「洪水安全指南」,内容包括:① 洪水来临前要做的1-2件事(如备足食物饮水、把贵重物品搬到高处);② 洪水期间要做和不要做的事(如立刻转移到高处、不要涉水);③ 一句鼓励大家做好准备的话。要求条理清晰、用上 Remember to… / Never… / It''s important to… 等安全指南常用句式。', 'Suppose you are a member of your school radio station. The rainy season has begun and floods are a common threat in your area. Write flood safety guidelines (about 80 words) including: 1) one or two things to do before a flood (e.g. store food and water, move valuables higher up); 2) what to do and what NOT to do during a flood (e.g. move to high ground at once, never walk through fast-moving water); 3) one sentence to encourage everyone to be prepared. Use expressions such as ''Remember to…'', ''Never…'', ''It''s important to…''.', '["灾前准备(Before a flood: store sufficient food and water; move valuables to a higher floor)","灾中行动(During a flood: move to high ground immediately; listen to warnings)","禁止事项(Never walk or drive through fast-moving water; do not drink flood water)","鼓励做好准备(Being prepared is the best way to stay safe.)"]'::jsonb, 70, 100, 'Flood Safety Guidelines
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U6', '{"title":"省略(Ellipsis)速查","intro":"为了不啰嗦,英语常把上文已出现、能从语境补回的重复成分省掉。判断口诀:省掉的部分一定能「原样补回」而句意不变。本单元三类:状语从句省略「主语+be」、并列/比较句省略重复动词(留助动词)、不定式只留 to 与对话省略。","table":{"headers":["省略类型","用法 / 例句 / 补回"],"rows":[["状语从句省「主语+be」","从句主语=主句主语时:When (you are) in trouble, call us. / Though (he was) tired, he kept on."],["主动留 -ing,被动留 -ed","While waiting(=we were waiting)… / If sent in time(=if it is sent)…"],["并列/比较留助动词","so/neither/nor/than/as 后省重复动词:He survived, and so did his cat.(did=survived)"],["不定式只留 to","I''d love to.(=to join) / I wanted to but couldn''t.(to 后省动词)"],["对话省略","—Did many lose their homes? —Yes, thousands did.(did=lost their homes)"]]},"specialRules":[{"rule":"状语从句省略的前提:从句与主句主语必须一致;不一致不能省","mark":"When warned, the villagers left.(villagers=被警告者)√"},{"rule":"主动关系留现在分词 -ing,被动关系留过去分词 -ed","mark":"While reading(主动) / When asked(被动)"},{"rule":"so/neither 后要倒装,助动词的时态/人称随被省的动词","mark":"so did I / neither has he"},{"rule":"不定式省略保留 to,但绝不保留后面的动词原形","mark":"I''d love to.(×I''d love to do.)"}],"why":["省略让句子更简洁、避免重复;只要被省的词能从上文唯一地补回来,句意就不受影响——这也是做题时判断「补什么、留什么」的依据。"],"gaokaoPoints":["状语从句中分词的主动(-ing)/被动(-ed)选择,是语法填空与改错的高频点。","so/neither/nor + 助动词 的倒装与时态一致;than/as 后省略动词留助动词。","不定式省略(代动词 to)与情态/助动词代替动词短语,常在完成句子与对话补全中考查。"],"examVsReal":[{"exam":"When (you are) crossing the road, be careful.（考试强调可补回的完整从句）","real":"Crossing the road, be careful.","note":"真实口语里连连词也常省,但考试更看重「主语一致+分词形式正确」"},{"exam":"—Will you help? —Yes, I will.(留助动词)","real":"—Will you help? —Sure!","note":"口语回答更随意;考试要求保留正确的助动词/to 来完成省略"}]}'::jsonb, 'fltrp');
